import { Canvas, useFrame, useLoader } from '@react-three/fiber';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

function Actor({ mounted, slug }) {
  const assetUri = `/assets/${slug}.glb`;
  const model = useLoader(GLTFLoader, assetUri);
  useFrame((_state, _delta) => { /* runtime callback is not resolved */ });
  return mounted && <mesh name="conditional-actor" dispose={null}><primitive object={model.scene} /></mesh>;
}

export function World({ mounted, slug }) {
  return <Canvas><Actor mounted={mounted} slug={slug} /></Canvas>;
}
